import Link from 'next/link';

export default function Forbidden() {
  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        minHeight: '100vh',
        fontFamily: 'system-ui, -apple-system, sans-serif',
        textAlign: 'center',
        padding: '2rem',
      }}
    >
      <h1
        style={{
          fontSize: '6rem',
          margin: '0',
          fontWeight: 700,
          color: '#e53e3e',
        }}
      >
        403
      </h1>
      <h2
        style={{
          fontSize: '1.5rem',
          margin: '0.5rem 0 1rem',
          fontWeight: 600,
          color: '#1a202c',
        }}
      >
        Forbidden
      </h2>
      <p
        style={{
          fontSize: '1rem',
          color: '#718096',
          maxWidth: '400px',
          lineHeight: 1.6,
          margin: '0 0 2rem',
